<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { profileRequest } from '../api'
const emit=defineEmits(['changed'])
const base='/api/v1/admin/capture-workspace'
const call=(path:string,method='GET',body?:unknown)=>profileRequest(base+path,{method,...(body!==undefined?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})})
const busy=ref(false),error=ref(''),providerOpen=ref(false),editorOpen=ref(false),resultOpen=ref(false)
const provider=ref<any>(null),targets=ref<any[]>([]),history=ref<any[]>([]),target=ref<any>(null),versions=ref<any[]>([]),state=ref<any>({revision:0}),selected=ref<number>(),preview=ref<any>(null),result=ref<any>(null)
const config=reactive({baseUrl:'',apiKey:'',clearKey:false,enabled:false,revision:0})
const creating=ref(false),name=ref(''),tool=ref('firecrawl'),targetRevision=ref(0),scopeEnabled=ref(false)
const rule=reactive<any>({url:'',itemSelector:'article',fields:[{name:'title',selector:'h2',attribute:'text',required:true},{name:'link',selector:'a',attribute:'href',required:false}],minItems:1,maxItems:100,waitMs:0,onlyMainContent:false})
async function guard(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e:any){error.value=e.message;ElMessage.error(e.message)}finally{busy.value=false}}
async function refresh(){const [overview,p,r]=await Promise.all([call(''),call('/web/provider'),call('/web/runs')]);targets.value=overview.targets.filter((t:any)=>t.onlineRule);provider.value=p;history.value=r}
const reload=()=>guard(refresh)
function providerDialog(){Object.assign(config,{baseUrl:provider.value.baseUrl,apiKey:'',clearKey:false,enabled:provider.value.enabled,revision:provider.value.revision});providerOpen.value=true}
async function saveProvider(){await guard(async()=>{provider.value=await call('/web/provider','PUT',config);config.apiKey='';providerOpen.value=false;ElMessage.success('服务配置已保存，下次执行生效')})}
function fresh(){creating.value=true;target.value=null;name.value='';tool.value='firecrawl';scopeEnabled.value=false;versions.value=[];selected.value=undefined;state.value={revision:0};preview.value=null;Object.assign(rule,{url:'',itemSelector:'article',fields:[{name:'title',selector:'h2',attribute:'text',required:true},{name:'link',selector:'a',attribute:'href',required:false}],minItems:1,maxItems:100,waitMs:0,onlyMainContent:false});editorOpen.value=true}
function selectVersion(version:number){const saved=versions.value.find(v=>v.version===version);if(saved){selected.value=version;Object.assign(rule,JSON.parse(JSON.stringify(saved.rule_json)));preview.value=null}}
async function loadRules(){const value=await call(`/web/targets/${target.value.target_key}/rules`);state.value=value.state;versions.value=value.versions}
async function edit(row:any){await guard(async()=>{target.value=row;name.value=row.name;tool.value=row.tool_key;targetRevision.value=row.revision;scopeEnabled.value=row.enabled;creating.value=false;await loadRules();preview.value=null;if(versions.value.length)selectVersion(state.value.draft_version);else{selected.value=undefined;rule.url=row.source_url}editorOpen.value=true})}
async function saveDraft(){await guard(async()=>{
 if(creating.value){target.value=await call('/targets','POST',{name:name.value,url:rule.url,toolKey:tool.value,fields:rule.fields.map((f:any)=>f.name).join('、'),notes:'在线声明式规则',enabled:false,revision:0});creating.value=false;state.value={revision:0};targetRevision.value=target.value.revision}
 const saved=await call(`/web/targets/${target.value.target_key}/rules`,'PUT',{revision:state.value.revision,rule});state.value=saved.state;versions.value=saved.versions;selected.value=state.value.draft_version;preview.value=null;await refresh();emit('changed');ElMessage.success('新草稿版本已保存，当前发布版本继续使用')
})}
const canonical=(value:any):any=>Array.isArray(value)?value.map(canonical):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(k=>[k,canonical(value[k])])):value
const dirty=()=>{const v=versions.value.find(v=>v.version===selected.value);return !v||JSON.stringify(canonical(v.rule_json))!==JSON.stringify(canonical(rule))}
async function test(){if(dirty()){ElMessage.warning('请先保存当前修改，再试抓该版本');return}await guard(async()=>{preview.value=await call(`/web/targets/${target.value.target_key}/preview`,'POST',{version:selected.value});result.value=preview.value;resultOpen.value=true;await refresh()})}
async function publish(){if(dirty()){ElMessage.warning('规则已修改，请先保存并重新试抓');return}await guard(async()=>{const value=await call(`/web/targets/${target.value.target_key}/publish`,'POST',{version:selected.value,revision:state.value.revision,previewId:preview.value.id});state.value=value.state;versions.value=value.versions;await refresh();target.value=targets.value.find(t=>t.target_key===target.value.target_key);targetRevision.value=target.value.revision;emit('changed');ElMessage.success(`版本${selected.value}已发布，下次执行立即使用`);})}
async function toggleEnabled(){await guard(async()=>{const t=target.value;await call('/targets/'+t.target_key,'PUT',{name:t.name,url:t.source_url,fields:rule.fields.map((f:any)=>f.name).join('、'),notes:t.notes,toolKey:t.tool_key,enabled:scopeEnabled.value,revision:targetRevision.value});await refresh();target.value=targets.value.find(v=>v.target_key===t.target_key);targetRevision.value=target.value.revision;emit('changed');ElMessage.success('定时范围已更新')})}
async function live(row:any){await guard(async()=>{result.value=await call(`/web/targets/${row.target_key}/run`,'POST');resultOpen.value=true;await refresh();emit('changed')})}
async function show(id:string){await guard(async()=>{result.value=await call('/web/runs/'+id);resultOpen.value=true})}
function download(){const u=URL.createObjectURL(new Blob([JSON.stringify(result.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=`web-capture-${result.value.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const label=(s:string)=>({SUCCEEDED:'校验通过',PARTIAL:'部分字段/数量不符',FAILED:'失败',RUNNING:'执行中',INTERRUPTED:'中断'}[s]||s)
onMounted(reload)
</script>
<template>
<div class="online-web">
 <div class="web-head"><div><h2>在线网页采集</h2><p>新增网站、微调字段、试抓发布。已发布的规则下次执行即时生效，无需重新部署。</p></div><div><el-button :disabled="busy" @click="reload">刷新</el-button><el-button :disabled="busy" @click="providerDialog">Firecrawl服务配置</el-button><el-button type="primary" :disabled="busy" @click="fresh">新增在线网站</el-button></div></div>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <div class="service-line">Firecrawl：<b>{{provider?.enabled?'已启用配置，实际连通性以试抓为准':'尚未启用'}}</b><span>{{provider?.selfHosted?'自建内部服务':'云端 / 自定义服务'}}</span><span>普通网页工具无需Key；动态渲染页面可使用Firecrawl。</span></div>
 <el-alert title="每条规则抓取一个公开网页，按CSS提取字段。源站登录、验证码和无限滚动不是通用规则自动解决的范围；通用结果与Top100榜单分开保存。" type="info" :closable="false"/>
 <el-empty v-if="!targets.length&&!busy" description="还没有在线规则网站，点击新增即可配置。"/>
 <el-table v-else :data="targets" stripe><el-table-column label="目标 / 工具" min-width="210"><template #default="{row}"><b>{{row.name}}</b><p>{{row.tool_key}}</p><a :href="row.source_url" target="_blank" rel="noopener noreferrer">查看网站 ↗</a></template></el-table-column><el-table-column label="规则状态" min-width="160"><template #default="{row}">草稿 {{row.ruleState?.draft_version||'无'}}<p>发布 {{row.ruleState?.published_version||'无'}} · {{row.enabled?'定时已纳入':'手动采集'}}</p></template></el-table-column><el-table-column label="最近执行" min-width="220"><template #default="{row}"><div v-for="r in row.webRuns?.slice(0,1)" :key="r.id"><el-button link type="primary" @click="show(r.id)">{{label(r.status)}} · v{{r.rule_version}}</el-button><p>{{r.error_code||r.run_mode}}</p></div></template></el-table-column><el-table-column label="管理" width="180"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="edit(row)">编辑 / 版本</el-button><el-button link type="primary" :disabled="busy||!row.ruleState?.published_version" @click="live(row)">执行已发布</el-button></template></el-table-column></el-table>
 <h3>网页执行记录</h3><el-table :data="history" stripe max-height="420"><el-table-column prop="source_url" label="来源URL" min-width="240"/><el-table-column prop="tool_key" label="工具" width="110"/><el-table-column label="版本 / 模式" width="140"><template #default="{row}">v{{row.rule_version}} · {{row.run_mode==='PREVIEW'?'试抓':'正式'}}</template></el-table-column><el-table-column label="结果" min-width="160"><template #default="{row}">{{label(row.status)}}<p>{{row.error_code}}</p></template></el-table-column><el-table-column label="数据" width="100"><template #default="{row}"><el-button link type="primary" @click="show(row.id)">查看结果</el-button></template></el-table-column></el-table>
 <el-dialog v-model="providerOpen" title="Firecrawl服务配置" width="min(620px,94vw)"><el-form label-position="top"><el-form-item label="API入口（包含 /v2）"><el-input v-model="config.baseUrl" placeholder="https://api.firecrawl.dev/v2"/></el-form-item><p>自建内部地址由服务器部署配置授权。无需Key的内部服务可留空；公网官方服务必须填Key。</p><el-form-item :label="provider?.apiKeyConfigured?'API Key（已保存，留空保持）':'API Key（未保存）'"><el-input v-model="config.apiKey" type="password" autocomplete="new-password" show-password/></el-form-item><el-checkbox v-model="config.clearKey">清空已保存Key</el-checkbox><el-form-item label="启用服务"><el-switch v-model="config.enabled"/></el-form-item></el-form><template #footer><el-button @click="providerOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveProvider">保存服务配置</el-button></template></el-dialog>
 <el-drawer v-model="editorOpen" title="网页规则 · 编辑、试抓与发布" size="min(1020px,96vw)" :close-on-click-modal="false">
  <el-form label-position="top"><div class="pair"><el-form-item label="网站名称"><el-input v-model="name" :disabled="!creating" maxlength="200"/></el-form-item><el-form-item label="抓取工具"><el-select v-model="tool" :disabled="!creating"><el-option value="firecrawl" label="Firecrawl（动态网页）"/><el-option value="web-http" label="普通HTTPS网页（无需Key）"/></el-select></el-form-item></div>
  <div v-if="versions.length" class="version-line"><span>查看版本 / 回退：</span><el-select v-model="selected" @change="selectVersion"><el-option v-for="v in versions" :key="v.version" :value="v.version" :label="`版本 ${v.version}${state.published_version===v.version?' · 当前发布':''}`"/></el-select><span>回退旧版本也需先试抓再发布。</span></div>
  <el-form-item label="页面URL（公开HTTPS；可带分页等非敏感参数）"><el-input v-model="rule.url" placeholder="https://example.com/games"/></el-form-item><el-form-item label="每条记录的CSS选择器"><el-input v-model="rule.itemSelector" placeholder="article 或 .game-card"/></el-form-item>
  <h3>需要获取的字段</h3><p class="muted">选择器相对每条记录；留空读取记录本身。字段名用英文，如title、link、developer。至少一个必填。</p>
  <div class="field-list"><div v-for="(f,i) in rule.fields" :key="i" class="field-row"><el-input v-model="f.name" placeholder="字段名" :aria-label="`字段${i+1}名称`"/><el-input v-model="f.selector" placeholder="相对CSS，如h2" :aria-label="`字段${i+1}选择器`"/><el-select v-model="f.attribute" :aria-label="`字段${i+1}属性`"><el-option v-for="a in ['text','href','src','content','datetime','title','alt']" :key="a" :value="a" :label="a==='text'?'文本':a"/></el-select><el-checkbox v-model="f.required">必填</el-checkbox><el-button text type="danger" :disabled="rule.fields.length===1" @click="rule.fields.splice(i,1)">删除</el-button></div></div>
  <el-button :disabled="rule.fields.length>=20" @click="rule.fields.push({name:'field'+(rule.fields.length+1),selector:'',attribute:'text',required:false})">添加字段</el-button>
  <div class="three"><el-form-item label="最低有效记录数"><el-input-number v-model="rule.minItems" :min="1" :max="1000"/></el-form-item><el-form-item label="最多记录数"><el-input-number v-model="rule.maxItems" :min="rule.minItems" :max="1000"/></el-form-item><el-form-item label="渲染等待（毫秒，仅Firecrawl）"><el-input-number v-model="rule.waitMs" :min="0" :max="10000" :step="500" :disabled="tool==='web-http'"/></el-form-item></div>
  <el-alert title="保存草稿不会改变当前发布规则。试抓真实访问来源并保存证据；校验通过才可发布。字段选择器匹配多个元素或数量不足会显示问题。" type="info" :closable="false"/>
  <div class="editor-actions"><el-button :loading="busy" @click="saveDraft">保存新草稿</el-button><el-button :disabled="busy||!selected" @click="test">试抓所选版本</el-button><el-button type="primary" :disabled="busy||preview?.status!=='SUCCEEDED'||preview?.rule_version!==selected" @click="publish">发布所选版本</el-button></div>
  <div v-if="state.published_version" class="scope"><b>当前发布：v{{state.published_version}}</b><el-checkbox v-model="scopeEnabled">纳入每天08:30、23:00采集</el-checkbox><el-button :disabled="busy" @click="toggleEnabled">保存定时范围</el-button></div>
  </el-form>
 </el-drawer>
 <el-drawer v-model="resultOpen" title="网页抓取结果与证据" size="min(1000px,96vw)">
  <template v-if="result"><h2>{{label(result.status)}} · v{{result.rule_version}}</h2><p class="url">{{result.source_url}}</p><p>{{result.tool_key}} · {{result.run_mode}} · {{result.started_at}}</p><el-alert v-if="result.error_code" :title="result.error_code" type="error" :closable="false"/><template v-if="result.result_json"><p>保存 {{result.result_json.result.actualCount}} 条 / 页面匹配 {{result.result_json.result.matchedCount}} 条</p><el-alert v-for="(issue,i) in result.result_json.result.issues" :key="i" :title="issue" type="warning" :closable="false"/><el-table :data="result.result_json.result.rows" stripe max-height="500"><el-table-column prop="position" label="行" width="60"/><el-table-column v-for="f in result.result_json.rule.fields" :key="f.name" :label="f.name" min-width="180"><template #default="{row}">{{row.fields[f.name]}}</template></el-table-column></el-table><details><summary>规则与字段定位证据</summary><pre>{{JSON.stringify(result.result_json,null,2)}}</pre></details></template><p class="url">材料 SHA256：{{result.raw_sha256||'尚未取得材料'}}</p><el-button @click="download">下载JSON结果</el-button></template>
 </el-drawer>
</div>
</template>
<style scoped>
.online-web{padding:10px 0}.web-head{display:flex;justify-content:space-between;gap:20px;align-items:center}.web-head h2{font-size:20px;margin:0 0 8px}.web-head p,.muted{color:#73839a;font-size:13px;line-height:1.7}.web-head>div:last-child{display:flex;gap:6px;flex-wrap:wrap}.web-head .el-button{margin:0}.service-line{display:flex;gap:14px;flex-wrap:wrap;padding:18px 0;color:#667b93;font-size:13px}.online-web h3{margin:24px 0 16px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}.three{display:flex;gap:24px;flex-wrap:wrap;margin-top:24px}.version-line{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0 24px;font-size:13px}.version-line .el-select{width:230px}.field-row{display:grid;grid-template-columns:1fr 1.5fr 110px 65px 60px;gap:10px;align-items:center;margin-bottom:12px}.editor-actions,.scope{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:25px 0}.url,pre{overflow-wrap:anywhere}pre{white-space:pre-wrap;font-size:12px;background:#f5f7fa;padding:16px}details{margin:20px 0}.online-web :deep(.el-alert){margin-bottom:12px}.online-web :deep(.cell){overflow-wrap:anywhere;word-break:normal}.scope{border-top:1px solid #e1e7ef;padding-top:20px}@media(max-width:850px){.web-head{display:block}.web-head>div:last-child{margin:15px 0}.pair{grid-template-columns:1fr}.field-row{grid-template-columns:1fr 1fr}.field-row .el-checkbox{margin:0}.field-list{border-top:1px solid #eee}.field-row{padding:14px 0;border-bottom:1px solid #eee}}
</style>
